/// double-start check).
Future<bool> hubHealthz(int port) async {
  try {
    final client = HttpClient()..connectionTimeout = const Duration(seconds: 1);
    final response = await (await client.get(
      '127.0.0.1',
      port,
      '/healthz',
    )).close();
    await response.drain<void>();
    client.close();
    return response.statusCode == 200;
  } on Object {
    return false;
  }
