      _connect(context).catchError((Object e, StackTrace s) {
        context.io.writeln('[hub] connect failed: $e');
      }),
    );
    context.registerSlashCommand(
      '/dap',
      (args) => _dapSlash(context, args),

      faBin ?? 'dart',
