      '$id/manifest.json': utf8.encode('{"id":"$id"}'),
      '$id/widget.js': utf8.encode('(function(){})();'),
      if ((catalog['widgets'] as List).any(
        (w) => w['id'] == id && w['icon'] != null,
      ))
        '$id/icon.svg': utf8.encode('<svg/>'),
    };
