  // not a bind error — `/dap start` probes first, but a manual double
  // start should be just as calm.
  if (await hubHealthz(spec.port)) {
    stdout.writeln('DAP hub already running on ws://127.0.0.1:${spec.port}/ws');
    return 0;
  }
