  Future<String> waitFor(
    Pattern pattern, {
    // 60 s (issue #943): the prototype's first frame pays the native-assets
    // build-hook cost; cold hooks cost 20-30 s on a loaded runner and blew
    // the old 20 s default (issue #936 vector 3 — CI now prewarms the
    // hooks, this is the headroom that keeps a cold cache from failing the
    // leg anyway).
    Duration timeout = const Duration(seconds: 60),
  }) async {
    final completer = Completer<String>();
    Timer? timer;
    timer = Timer(timeout, () {
      if (!completer.isCompleted) {
        completer.completeError(
          TimeoutException('pattern not found: $pattern\noutput:\n$_buffer'),
        );
      }
    });
    void check([Object? _]) {
      if (_buffer.toString().contains(pattern) && !completer.isCompleted) {
        timer?.cancel();
        completer.complete(_buffer.toString());
      }
    }

    check();
    if (!completer.isCompleted) {
      // Poll the buffer periodically; the stream is single-subscription and
      // already owned by this collector.
      final poll = Timer.periodic(const Duration(milliseconds: 20), check);
      try {
        await completer.future;
      } finally {
        poll.cancel();
      }
    }
    return completer.future;
  }

  Future<void> close() => _sub.cancel();
}

