      await sub.cancel();
      await blocker.close();
    });
    final code = await runHubCommand(
      ['serve', '--port', '$port'],
      home: tempHome.path,
      environment: {envHubPidFile: '${tempHome.path}/hub.pid'},
    );
    expect(code, 1);

