+/// The outcome of one bind attempt or the bounded retry window
+/// (issue #943, vector 2).
+enum _BindOutcome {
+  /// The hub bound its port and may serve.
+  bound,
+
+  /// A hub came up on the port mid-retry — the idempotent no-op exit.
+  alreadyRunning,
+
