    'serve against a live hub: idempotent no-op, exit 0, no pid file',
    () async {
      final port = await freePort();
      final hub = LocalHub(port: port, stateFile: stateFileFor());
      await hub.start();
      addTearDown(() => hub.stop());
      final pidFile = File('${tempHome.path}/hub.pid');
