  /// Sends Ctrl+C.
  void sendCtrlC() => pty.write('\x03');

  /// Sends Arrow Up.
  void sendArrowUp() => pty.write('\x1b[A');

  /// Sends Arrow Down.
  void sendArrowDown() => pty.write('\x1b[B');

