      () async {
    final probe = LocalHub(port: 0);
    await probe.start();
    final port = probe.url.port;
    await probe.stop();

    final blocker = await ServerSocket.bind('127.0.0.1', port);
    var accepts = 0;
    final firstConnection = Completer<void>();
    final sub = blocker.listen((socket) {
      accepts++;
      socket.destroy();
      if (!firstConnection.isCompleted) firstConnection.complete();
    });
    unawaited(
      firstConnection.future.then((_) async {
        await sub.cancel();
        await blocker.close();
      }),
    );
    addTearDown(() async {
      await sub.cancel();
      await blocker.close();
    });
    final code = await runHubCommand(
