/// Serves the hub: idempotent against a live one, pid-state
/// bookkeeping for `fa dap stop`, then the serve loop ([serveLoop] is
/// the seam tests cut short; production blocks until killed).
Future<int> hubServe(
  HubServeSpec spec, {
  required File stateFile,
  required File pidFile,
  String? secret,
  Future<void> Function(LocalHub hub, File pidFile)? serveLoop,
}) async {
  // Idempotent: a second `fa hub serve` against a live hub is a no-op,
  // not a bind error — `/dap start` probes first, but a manual double
  // start should be just as calm.
  if (await hubHealthz(spec.port)) {
    stdout.writeln('DAP hub already running on ws://127.0.0.1:${spec.port}/ws');
    return 0;
  }
  final refusal = hubLanSecretRefusal(bind: spec.flagBind, secret: [REDACTED:Sensitive Value]);
  if (refusal != null) {
    stderr.writeln(refusal);
    return 1;
  }
  final hub = LocalHub(
    port: spec.port,
    bind: spec.flagBind ?? 'loopback',
    masterSecret: secret,
    stateFile: stateFile,
    relayAllowAnyHost: spec.relayAllowAnyHost,
  );
  final (outcome, bindError) = await _bindWithRetry(hub, spec.port);
  switch (outcome) {
    case _BindOutcome.alreadyRunning:
      stdout.writeln('DAP hub already running on ws://127.0.0.1:${spec.port}/ws');
      return 0;
    case _BindOutcome.refused:
      stderr.writeln(
        'hub: cannot bind 127.0.0.1:${spec.port} ($bindError) — '
        'something else holds the port',
      );
      return 1;
    case _BindOutcome.bound:
      break;
    case _BindOutcome.retry:
