  _writePidState(
    pidFile,
    pid,
    spec.port,
    relaySecret: hub.isProtected ? null : hub.relaySecret,
  );
  stdout.writeln(
    'DAP hub on ${hub.url}${hub.isProtected ? ' (password-protected)' : ''}',
  );
  _printRelayHint(hub, pidFile);
  if (spec.flagBind == 'lan') await _printLanPeerUrls(hub);
