  Future<int> freePort() async {
    final probe = LocalHub(port: 0);
    await probe.start();
    final port = probe.url.port;
    await probe.stop();
    return port;
  }

  File stateFileFor() =>
      defaultHubStateFile(home: tempHome.path, environment: const {});

