{"content":"// THROWAWAY review probe — verifies the committed 2-accept logic actually
// drives the retry path. Mirrors fah_hub_serve_ports_test.dart verbatim plus
// an accept-count print. Deleted after the check.
import 'dart:async';
import 'dart:io';

import 'package:flutter_agent_harness/io.dart' show LocalHub;
import 'package:test/test.dart';

import '../../bin/fah_dap_command.dart' show envHubPidFile;
import '../../bin/fah_hub_serve.dart';

void main() {
  late Directory tempHome;

  setUp(() async {
    tempHome = await Directory.systemTemp.createTemp('probe-retry2-');
  });

  tearDown(() async {
    if (await tempHome.exists()) tempHome.deleteSync(recursive: true);
  });

  test('probe: committed 2-accept close drives the retry', () async {
    final probe = LocalHub(port: 0);
    await probe.start();
    final port = probe.url.port;
    await probe.stop();

    final blocker = await ServerSocket.bind('127.0.0.1', port);
    var accepts = 0;
    final secondAccepted = Completer<void>();
    final sub = blocker.listen((socket) {
      socket.destroy();
      accepts++;
      if (accepts == 2 && !secondAccepted.isCompleted) {
        secondAccepted.complete();
      }
    });
    unawaited(
      secondAccepted.future.then((_) async {
        await sub.cancel();
        await blocker.close();
      }),
    );
    addTearDown(() async {
      await sub.cancel();
      await blocker.close();
    });
    final code = await runHubCommand(
      ['serve', '--port', '$port'],
      home: tempHome.path,
      environment: {envHubPidFile: '${tempHome.path}/hub.pid'},
      serveLoop: (hub, _) async => hub.stop(),
    );
    expect(code, 0);
    // ignore: avoid_print
    print('PROBE-RESULT: accepts=$accepts (retry '
        '${accepts >= 2 ? 'DRIVEN' : 'NOT driven'})');
  }, timeout: const Timeout(Duration(seconds: 20)));
}
